class Cache {
    private val mutex = Mutex()
    private val entries = mutableMapOf<String, Entry>()

    suspend fun find(key: String): Entry = mutex.withLock {
        entries[key] ?: insertImpl(key)      // mutex held: no re-acquisition
    }

    private fun insertImpl(key: String) =      // must not lock or suspend
        Entry(key).also { entries[key] = it }
}

private val lock = Any()

fun find(key: String): Entry = synchronized(lock) {   // monitor held (reentrant)
    entries[key] ?: insertImpl(key)
}

private fun insertImpl(key: String): Entry =   // assumes the monitor is held
    Entry(key).also { entries[key] = it }

